cd /app && mkdir -p output/assets && cat > output/assets/styles.css << 'EOF'
:root {
  --navy: #0a1628;
  --navy-2: #11253f;
  --slate: #4d5a6b;
  --gray-100: #f2f5f8;
  --gray-200: #e3e8ef;
  --gray-300: #cfd7e3;
  --white: #ffffff;
  --accent: #0f8b8d;
  --accent-gold: #c4a354;
  --text: #1b2737;
  --max: 1200px;
  --radius: 10px;
  --shadow: 0 10px 30px rgba(10, 22, 40, 0.12);
}
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: Inter, "Segoe UI", Roboto, Arial, sans-serif;
  color: var(--text);
  background: var(--white);
  line-height: 1.6;
}
h1,h2,h3,h4 { font-family: "Merriweather", Georgia, serif; line-height: 1.2; margin: 0 0 12px; color: var(--navy); }
p { margin: 0 0 14px; }
a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
.container { width: min(var(--max), 92%); margin: 0 auto; }
.btn {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 11px 18px; border-radius: 999px; border: 1px solid transparent;
  font-weight: 600; font-size: 14px; cursor: pointer;
}
.btn-primary { background: var(--accent); color: var(--white); }
.btn-primary:hover { filter: brightness(1.08); }
.btn-outline { border-color: var(--gray-300); color: var(--navy); }
.top-banner { background: var(--navy); color: #d8e0ea; padding: 10px 0; font-size: 14px; }
.top-banner .container { display: flex; justify-content: space-between; gap: 14px; flex-wrap: wrap; }
header.main-header {
  position: sticky; top: 0; z-index: 1000;
  background: rgba(10,22,40,0.97); color: var(--white);
  backdrop-filter: blur(6px);
  border-bottom: 1px solid rgba(255,255,255,0.1);
}
.nav-wrap { display: flex; align-items: center; justify-content: space-between; min-height: 74px; }
.logo { font-weight: 800; letter-spacing: .4px; font-size: 22px; }
.logo span { color: var(--accent-gold); }
.desktop-nav { display: flex; align-items: center; gap: 24px; }
.desktop-nav > a, .nav-trigger { font-size: 14px; color: #ecf2f9; padding: 24px 0; border: 0; background: none; cursor: pointer; }
.nav-item-services { position: relative; }
.mega-menu {
  position: absolute; left: 50%; transform: translateX(-50%);
  top: calc(100% + 2px); width: min(980px, 92vw);
  background: #ffffff; color: var(--text); border-radius: 14px;
  box-shadow: var(--shadow); padding: 28px; display: none;
  grid-template-columns: 2fr 1.1fr; gap: 32px;
}
.nav-item-services.open .mega-menu { display: grid; }
.mega-menu h4 { font-size: 15px; margin-bottom: 10px; color: var(--navy); font-family: Inter, sans-serif; text-transform: uppercase; letter-spacing: .06em; }
.mega-grid { display: grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap: 10px 20px; }
.mega-link { padding: 10px; border-radius: 8px; border: 1px solid var(--gray-200); }
.mega-link:hover { border-color: var(--accent); }
.mega-link strong { display: block; color: var(--navy); font-size: 14px; }
.mega-link span { color: var(--slate); font-size: 13px; }
.mega-types a { display:block; padding: 8px 0; color: var(--slate); border-bottom:1px solid var(--gray-200); }
.mobile-toggle { display: none; background:none;border:0;color:white;font-size:28px; }
.mobile-nav {
  display: none; background: var(--navy); border-top: 1px solid rgba(255,255,255,.12);
  padding: 12px 0 18px;
}
.mobile-nav a, .mobile-acc-btn {
  display: block; width: 100%; color: #e8eff8; padding: 12px 0;
  background:none;border:0;text-align:left;font-size:15px;
}
.mobile-acc-panel { display:none; padding: 0 0 8px 12px; }
.mobile-acc-item.open .mobile-acc-panel { display:block; }
.hero {
  min-height: 64vh; color: white; position: relative;
  display: flex; align-items: center;
  background-size: cover; background-position: center;
}
.hero::before {
  content: ""; position: absolute; inset: 0;
  background: linear-gradient(120deg, rgba(10,22,40,.85), rgba(10,22,40,.38));
}
.hero .container { position: relative; z-index: 1; }
.hero h1 { color: white; font-size: clamp(2rem, 5vw, 3.4rem); }
.hero p { color: #d9e4f0; max-width: 760px; }
.section { padding: 70px 0; }
.section.alt { background: var(--gray-100); }
.grid-3 { display:grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap:24px; }
.grid-2 { display:grid; grid-template-columns: repeat(2,minmax(0,1fr)); gap:24px; }
.card {
  background:white; border:1px solid var(--gray-200); border-radius: var(--radius);
  padding: 22px; box-shadow: 0 3px 10px rgba(11,23,39,.04);
}
.card h3 { font-size: 22px; }
.kicker { text-transform: uppercase; letter-spacing: .08em; font-size: 12px; color: var(--accent); font-weight: 700; }
.split { display:grid; grid-template-columns: 1.2fr 1fr; gap:32px; align-items:start; }
.tabs-wrap { display:grid; grid-template-columns: 280px 1fr; gap:26px; }
.tabs-nav button {
  width:100%; text-align:left; border:1px solid var(--gray-200); background:#fff;
  margin-bottom:10px; padding:14px 16px; border-radius:8px; font-weight:600; color:var(--navy);
}
.tabs-nav button.active { border-color: var(--accent); background:#edf7f7; }
.tab-panel { display:none; }
.tab-panel.active { display:block; }
.insight-list .card img { border-radius:8px; margin-bottom:14px; height:170px; object-fit:cover; width:100%; }
.footer { background: var(--navy); color: #d0d8e4; padding: 48px 0 30px; }
.footer-grid { display:grid; grid-template-columns: 2fr 1fr 1fr; gap:26px; }
.footer a { color:#d0d8e4; display:block; margin:7px 0; font-size:14px; }
.cap-grid { display:grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap:20px; }
.breadcrumbs { font-size:14px; color:#506178; margin: 20px 0 4px; }
.partner-carousel { position: relative; overflow: hidden; border-radius: var(--radius); }
.carousel-track { display:flex; transition: transform .45s ease; }
.carousel-slide { min-width: 100%; background: white; border:1px solid var(--gray-200); padding:24px; }
.carousel-controls { display:flex; gap:8px; margin-top:12px; }
.carousel-controls button { border:1px solid var(--gray-300); background:white; padding:8px 12px; border-radius:6px; cursor:pointer; }
.newsletter { background: linear-gradient(120deg,#0f213a,#12365f); color:white; border-radius: 14px; padding: 28px; }
.newsletter input { width:100%; padding:12px; border-radius:8px; border:1px solid #ffffff40; background:#ffffff14; color:white; margin:8px 0 12px; }
@media (max-width: 980px) {
  .desktop-nav { display:none; }
  .mobile-toggle { display:block; }
  .mobile-nav.open { display:block; }
  .grid-3, .grid-2, .cap-grid, .split, .tabs-wrap, .footer-grid { grid-template-columns: 1fr; }
  .hero { min-height: 58vh; }
}
EOF

